import{_ as t,c as o,o as s,ae as a}from"./chunks/framework.CliRSA9F.js";const r="/images/ai_mentions.webp",m=JSON.parse('{"title":"AI Mentions","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-mentions.md","filePath":"features/ai-mentions.md"}'),i={name:"features/ai-mentions.md"};function n(l,e,h,d,c,u){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="ai-mentions" tabindex="-1">AI Mentions <a class="header-anchor" href="#ai-mentions" aria-label="Permalink to &quot;AI Mentions&quot;">​</a></h1><h2 id="track-your-podcast-s-visibility-across-ai-platforms" tabindex="-1">Track Your Podcast&#39;s Visibility Across AI Platforms <a class="header-anchor" href="#track-your-podcast-s-visibility-across-ai-platforms" aria-label="Permalink to &quot;Track Your Podcast&#39;s Visibility Across AI Platforms&quot;">​</a></h2><p>AI Mentions shows how often major AI platforms recommend your podcast when users ask for suggestions. As more listeners turn to ChatGPT, Claude, Perplexity, and Gemini for podcast recommendations, understanding your visibility across these platforms becomes essential for growth.</p><p><img src="'+r+'" alt="AI Mentions Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>AI Visibility</strong> in the sidebar, then open the <strong>AI Mentions</strong> tab.</p><h2 id="why-ai-visibility-matters" tabindex="-1"><strong>Why AI Visibility Matters</strong> <a class="header-anchor" href="#why-ai-visibility-matters" aria-label="Permalink to &quot;**Why AI Visibility Matters**&quot;">​</a></h2><p>The way people discover podcasts is changing. Beyond traditional search and browse, listeners increasingly ask AI assistants questions like &quot;What are the best business podcasts?&quot; or &quot;Recommend podcasts about true crime.&quot; When AI recommends your podcast, you gain access to an entirely new discovery channel.</p><p>PodSEO tracks recommendations from four major AI platforms:</p><ul><li><strong>ChatGPT</strong> (OpenAI)</li><li><strong>Claude</strong> (Anthropic)</li><li><strong>Perplexity</strong></li><li><strong>Gemini</strong> (Google)</li></ul><p>Each platform uses different data sources and recommendation algorithms, so your visibility can vary significantly across them.</p><h3 id="what-podseo-monitors" tabindex="-1"><strong>What PodSEO Monitors</strong> <a class="header-anchor" href="#what-podseo-monitors" aria-label="Permalink to &quot;**What PodSEO Monitors**&quot;">​</a></h3><p>To measure this, PodSEO monitors <strong>900+ topics</strong> — the kinds of things listeners actually ask about, spanning genres, audiences, listening contexts, intents, and formats (for example, &quot;best business podcasts,&quot; &quot;podcasts for a long commute,&quot; or &quot;shows to help me fall asleep&quot;). For each topic, PodSEO asks all four AI assistants which podcasts they recommend, then records where your show appears. This is how your dashboard reflects real recommendation behavior across the AI landscape rather than a single spot check.</p><h2 id="understanding-your-ai-visibility-dashboard" tabindex="-1"><strong>Understanding Your AI Visibility Dashboard</strong> <a class="header-anchor" href="#understanding-your-ai-visibility-dashboard" aria-label="Permalink to &quot;**Understanding Your AI Visibility Dashboard**&quot;">​</a></h2><h3 id="preparing-your-results" tabindex="-1"><strong>Preparing Your Results</strong> <a class="header-anchor" href="#preparing-your-results" aria-label="Permalink to &quot;**Preparing Your Results**&quot;">​</a></h3><p>When you first open AI Mentions for a podcast, you may see <strong>Preparing your AI visibility results</strong> while PodSEO checks your topics with the AI assistants. The page updates automatically once results are ready. If your topics haven&#39;t been checked yet, the page lets you know that results will appear after they&#39;re checked.</p><h3 id="the-last-8-weeks" tabindex="-1"><strong>The Last 8 Weeks</strong> <a class="header-anchor" href="#the-last-8-weeks" aria-label="Permalink to &quot;**The Last 8 Weeks**&quot;">​</a></h3><p>Your dashboard is built from <strong>recent results—the last 8 weeks</strong>. The summary numbers, provider breakdown, and chart all reflect mentions recorded in that window, and the chart shows the exact date range it covers. Older results are still shown where they&#39;re useful (marked as older), but they don&#39;t count toward your recent numbers.</p><h3 id="ai-visibility-score" tabindex="-1"><strong>AI Visibility Score</strong> <a class="header-anchor" href="#ai-visibility-score" aria-label="Permalink to &quot;**AI Visibility Score**&quot;">​</a></h3><p>Your AI Visibility Score (0-100) provides a snapshot of how well your podcast performs across AI recommendations, based on the latest mentions recorded within the last 8 weeks. The score considers:</p><ul><li><strong>Topic coverage</strong> — How many topics your podcast appears in</li><li><strong>Provider coverage</strong> — How many of the four AI platforms mention you</li><li><strong>Consistency</strong> — Whether you appear regularly across multiple providers</li></ul><p>A higher score indicates stronger overall AI visibility and more opportunities for discovery.</p><h3 id="summary-numbers-and-weekly-change" tabindex="-1"><strong>Summary Numbers and Weekly Change</strong> <a class="header-anchor" href="#summary-numbers-and-weekly-change" aria-label="Permalink to &quot;**Summary Numbers and Weekly Change**&quot;">​</a></h3><p>Next to the score, three summary numbers give you the big picture:</p><ul><li><strong>Topics</strong> — How many topics have mentions of your podcast</li><li><strong>Providers</strong> — How many of the four assistants are mentioning you</li><li><strong>Inner circle</strong> — How many topics are mentioned by 2 or more assistants</li></ul><p>The score and each number show a <strong>vs last week</strong> change, so you can quickly see whether your AI visibility is growing, shrinking, or flat.</p><h3 id="topics-mentioned-over-time" tabindex="-1"><strong>Topics Mentioned Over Time</strong> <a class="header-anchor" href="#topics-mentioned-over-time" aria-label="Permalink to &quot;**Topics Mentioned Over Time**&quot;">​</a></h3><p>The <strong>Topics mentioned over time</strong> chart tracks how many of your topics received mentions across recent periods. Hover over or tap a point on the chart to open the list of topics mentioned in that period. (Keyboard users can focus the chart, use the Left/Right arrow keys to choose a period, and press Enter to view its topics.)</p><h3 id="previously-mentioned" tabindex="-1"><strong>Previously Mentioned</strong> <a class="header-anchor" href="#previously-mentioned" aria-label="Permalink to &quot;**Previously Mentioned**&quot;">​</a></h3><p>The <strong>Previously mentioned</strong> section lists topics where assistants mentioned your podcast recently but not in their latest results. Each entry shows the topic, when your podcast was <strong>Last seen</strong> there, and which assistants previously mentioned you. Use this list to spot topics you&#39;re at risk of losing.</p><h3 id="provider-breakdown" tabindex="-1"><strong>Provider breakdown</strong> <a class="header-anchor" href="#provider-breakdown" aria-label="Permalink to &quot;**Provider breakdown**&quot;">​</a></h3><p>See exactly which AI platforms recommend your podcast and for which topics. Each provider card (ChatGPT, Claude, Perplexity, Gemini) shows:</p><ul><li>How many topics have recent mentions from that assistant, with the topic names</li><li>How many topics have older results (outside the recent window)</li><li><strong>Last result</strong> — the date of that assistant&#39;s most recent result</li><li>How many of your topics were checked in the last 8 weeks (for example, &quot;40 of 52 topics checked in the last 8 weeks&quot;)</li></ul><p>If an assistant was checked but didn&#39;t mention you, the card says &quot;No mentions in recent results.&quot;</p><h3 id="your-topics" tabindex="-1"><strong>Your topics</strong> <a class="header-anchor" href="#your-topics" aria-label="Permalink to &quot;**Your topics**&quot;">​</a></h3><p>Topic cards show your performance for individual topics like &quot;Business Podcasts,&quot; &quot;True Crime,&quot; or &quot;Podcasts for Entrepreneurs.&quot; Each card displays:</p><ul><li>The topic and its type</li><li>An <strong>Inner</strong> or <strong>Outer</strong> badge</li><li><strong>Last checked</strong> date (or <strong>Last mentioned</strong> date plus an <strong>Older result</strong> badge if the topic&#39;s latest result is outside the recent window)</li><li>Your frequency percentage</li><li>Your rank among the podcasts mentioned for that topic</li></ul><p>Click any topic card to open its details. The top of the window shows <strong>Your podcast by assistant</strong>: for each assistant, whether it mentioned you, when it was checked, and—where relevant—when it last mentioned you. Below that is the topic&#39;s full leaderboard of mentioned podcasts. If the topic&#39;s results are older, the window notes that they&#39;re older saved results and are not included in your recent score.</p><h3 id="understanding-frequency" tabindex="-1"><strong>Understanding Frequency</strong> <a class="header-anchor" href="#understanding-frequency" aria-label="Permalink to &quot;**Understanding Frequency**&quot;">​</a></h3><p>On AI Mentions, <strong>frequency</strong> is the share of the four AI assistants that mention your podcast for a topic. If two of the four assistants mention you, your frequency for that topic is 50%; if all four do, it&#39;s 100%. It&#39;s always measured against all four assistants, so a topic checked by only one assistant can&#39;t look like full coverage.</p><p>These are observations from the answers PodSEO collected, not a promise about what any individual listener will be told — assistants change their answers, and a real user&#39;s phrasing, location, and conversation history can all shift the result. (The <a href="/features/ai-leaderboard.html">AI Leaderboards</a> tab uses a different, week-by-week frequency measure; see that article for details.)</p><h3 id="inner-circle-topics" tabindex="-1"><strong>Inner Circle Topics</strong> <a class="header-anchor" href="#inner-circle-topics" aria-label="Permalink to &quot;**Inner Circle Topics**&quot;">​</a></h3><p>Topics where your podcast is mentioned by <strong>2 or more of the 4 assistants</strong> are marked as &quot;Inner Circle&quot; topics (you&#39;ll see &quot;Inner circle = 2+ assistants&quot; on the page). These represent your strongest areas of AI visibility — topics where more than one assistant independently associates your podcast with the subject. Topics mentioned by only one assistant are marked &quot;Outer.&quot;</p><p>Building more Inner Circle topics should be a key goal, as it indicates robust visibility that doesn&#39;t depend on any single AI platform.</p><h3 id="knowledge-check" tabindex="-1"><strong>Knowledge Check</strong> <a class="header-anchor" href="#knowledge-check" aria-label="Permalink to &quot;**Knowledge Check**&quot;">​</a></h3><p>At the bottom of the page, the <strong>Knowledge check</strong> card links to <a href="/features/knowledge-check.html">Knowledge Check</a>, where you can ask each assistant directly about your podcast and see where its knowledge differs from your own materials.</p><p>Note that mentions reflect saved AI responses, not listener referrals.</p><h2 id="how-to-improve-your-ai-visibility" tabindex="-1"><strong>How to Improve Your AI Visibility</strong> <a class="header-anchor" href="#how-to-improve-your-ai-visibility" aria-label="Permalink to &quot;**How to Improve Your AI Visibility**&quot;">​</a></h2><h3 id="optimize-your-podcast-metadata" tabindex="-1"><strong>Optimize Your Podcast Metadata</strong> <a class="header-anchor" href="#optimize-your-podcast-metadata" aria-label="Permalink to &quot;**Optimize Your Podcast Metadata**&quot;">​</a></h3><p>AI systems analyze your podcast title, description, and episode content to understand what topics you cover. Clear, descriptive metadata helps AI accurately categorize and recommend your podcast.</p><ul><li>Use natural language that describes your content clearly</li><li>Include relevant topic keywords in your show description</li><li>Ensure episode titles reflect the actual content</li></ul><h3 id="build-authority-in-your-niche" tabindex="-1"><strong>Build Authority in Your Niche</strong> <a class="header-anchor" href="#build-authority-in-your-niche" aria-label="Permalink to &quot;**Build Authority in Your Niche**&quot;">​</a></h3><p>AI recommendations favor podcasts that demonstrate expertise and consistent quality in specific topics. Focus on:</p><ul><li>Publishing regular, high-quality content in your core topics</li><li>Building a track record of episodes that serve your target audience</li><li>Developing clear positioning that AI can recognize</li></ul><h3 id="expand-your-web-presence" tabindex="-1"><strong>Expand Your Web Presence</strong> <a class="header-anchor" href="#expand-your-web-presence" aria-label="Permalink to &quot;**Expand Your Web Presence**&quot;">​</a></h3><p>This is often the single biggest lever for AI visibility. AI assistants build their recommendations largely from what they read on the open web — and they tend to be <strong>more responsive to websites that recommend podcasts than to the listening platforms themselves</strong>. When your show appears in a &quot;best [topic] podcasts&quot; listicle, a review site, a newsletter, or an industry article, that&#39;s exactly the kind of source an assistant draws on to answer &quot;what should I listen to?&quot;</p><p>That makes AI visibility closely tied to your <strong><a href="/features/pr-outreach.html">PR &amp; Media Coverage</a></strong> efforts:</p><ul><li>Use <strong><a href="/features/pr-outreach.html">PR Outreach</a></strong> to actively pitch your podcast to the newsletters, blogs, directories, and listicle publishers most likely to recommend shows like yours. Earning placements in those &quot;best of&quot; roundups is one of the most direct ways to increase how often AI assistants surface your podcast.</li><li>Use <strong><a href="/features/my-placements.html">My Placements</a></strong> to track the web links and editorial features you&#39;ve already earned, so you can see which sources are feeding your discoverability.</li></ul><p>Because a single well-placed listicle can be read by every assistant, growing these web mentions frequently moves your AI visibility more than optimizing any one platform.</p><h3 id="monitor-and-adapt" tabindex="-1"><strong>Monitor and Adapt</strong> <a class="header-anchor" href="#monitor-and-adapt" aria-label="Permalink to &quot;**Monitor and Adapt**&quot;">​</a></h3><p>Check your AI Visibility dashboard regularly to spot trends:</p><ul><li>New topics where you&#39;re gaining visibility</li><li>Providers where your visibility is changing</li><li>Opportunities to strengthen weak areas</li></ul><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>AI Mentions works alongside other PodSEO features to give you a complete picture of your podcast&#39;s discoverability:</p><ul><li><strong><a href="/features/pr-outreach.html">PR Outreach</a></strong> — Earn mentions on the listicles, newsletters, and review sites that AI assistants read most; this is one of the strongest ways to lift AI visibility</li><li><strong><a href="/features/my-placements.html">My Placements</a></strong> — Track the web links and editorial features you&#39;ve earned, the same web signals that feed AI recommendations</li><li><strong><a href="/features/ai-leaderboard.html">AI Leaderboard</a></strong> — See which podcasts AI recommends most for any topic, not just your own</li><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — Traditional search keywords complement AI visibility</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>AI Mentions is available on paid plans. Free users see a locked preview filled with sample data, along with an option to upgrade and unlock their podcast&#39;s actual AI visibility. The dashboard updates regularly as PodSEO queries AI platforms for the latest recommendations.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Treat AI visibility and PR as one effort: use <a href="/features/pr-outreach.html">PR Outreach</a> to land spots in &quot;best [topic] podcasts&quot; listicles and roundups — AI assistants weigh these web recommendations heavily</li><li>Use <a href="/features/ai-leaderboard.html">AI Leaderboard</a> to research competitors and discover topic opportunities</li><li>Combine AI visibility insights with your <a href="/features/keyword-strategy.html">Keyword Strategy</a> to optimize for both traditional search and AI discovery</li><li>Focus on building Inner Circle topics — consistent visibility across all providers is more valuable than strong presence on just one</li><li>Clear positioning in your metadata helps AI platforms understand and categorize your podcast accurately</li></ul>',69)])])}const y=t(i,[["render",n]]);export{m as __pageData,y as default};
